<?php
use App\Models\AuditLog; use App\Models\Event; use App\Models\Rsvp; use Illuminate\Database\Eloquent\Builder; use Livewire\Component;
new class extends Component { public ?int $rsvpId=null; public string $status='pending'; public string $attendingCount='0'; public string $notes=''; public function mount(?int $rsvpId=null):void{$this->rsvpId=$rsvpId;abort_unless(auth()->user()?->can('rsvps.update'),403);$r=$this->accessibleRsvps()->with('invitation.recipient','invitation.event')->findOrFail($rsvpId);$this->status=$r->status;$this->attendingCount=(string)$r->attending_count;$this->notes=$r->notes??'';} public function save():void{$d=$this->validate(['status'=>['required','in:pending,attending,not_attending,cancelled'],'attendingCount'=>['required','integer','min:0','max:999'],'notes'=>['nullable','string','max:1000']]);$r=$this->accessibleRsvps()->with('invitation')->findOrFail($this->rsvpId);$oldValues=['status'=>$r->status,'attending_count'=>$r->attending_count,'notes'=>$r->notes];$newValues=['status'=>$d['status'],'attending_count'=>$d['status']===Rsvp::STATUS_ATTENDING?$d['attendingCount']:0,'notes'=>$d['notes']?:null];$r->update(['status'=>$d['status'],'attending_count'=>$d['status']===Rsvp::STATUS_ATTENDING?$d['attendingCount']:0,'notes'=>$d['notes']?:null]);AuditLog::query()->create(['actor_id'=>auth()->id(),'event_id'=>$r->invitation->event_id,'action'=>'rsvp.updated','subject_type'=>Rsvp::class,'subject_id'=>$r->getKey(),'old_values'=>$oldValues,'new_values'=>$newValues,'ip_address'=>request()->ip(),'user_agent'=>request()->userAgent()]);session()->flash('success','RSVP berhasil diperbarui.');$this->redirectRoute('admin.rsvps');} private function accessibleRsvps():Builder{return Rsvp::query()->whereHas('invitation',fn(Builder $q):Builder=>$q->whereIn('event_id',$this->accessibleEvents()->select('id')));} private function accessibleEvents():Builder{$u=auth()->user();return Event::query()->when(!$u->hasRole('Super Admin'),fn(Builder $q):Builder=>$q->where(fn(Builder $q):Builder=>$q->where('created_by',$u->getKey())->orWhereHas('admins',fn(Builder $q):Builder=>$q->whereKey($u->getKey()))));} };
?>
<div class="mx-auto max-w-3xl space-y-8"><div class="flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-semibold text-brand-950">Edit RSVP</h1></div><a href="{{ route('admin.rsvps') }}" class="rounded-xl border border-slate-300 px-5 py-3 text-sm font-semibold text-slate-700">Kembali</a></div><form wire:submit="save" class="space-y-5 rounded-3xl border border-slate-200 bg-white p-6 sm:p-8"><div><label class="text-sm font-semibold text-slate-700">Status</label><select wire:model="status" class="mt-2 w-full px-4 py-3"><option value="pending">Pending</option><option value="attending">Hadir</option><option value="not_attending">Tidak hadir</option><option value="cancelled">Dibatalkan</option></select></div><div><label class="text-sm font-semibold text-slate-700">Jumlah hadir</label><input wire:model="attendingCount" type="number" min="0" class="mt-2 w-full px-4 py-3"></div><div><label class="text-sm font-semibold text-slate-700">Catatan</label><textarea wire:model="notes" rows="4" class="mt-2 w-full px-4 py-3"></textarea></div><div class="flex justify-end gap-3"><a href="{{ route('admin.rsvps') }}" class="rounded-xl border border-slate-300 px-5 py-3 font-semibold text-slate-700">Batal</a><button class="rounded-xl bg-brand-950 px-5 py-3 font-semibold text-white">Simpan RSVP</button></div></form></div>